//! Head-relative reflection cues through control and worker preparation.

use crate::{BinauralDecoderPlugin,RoomModel};
use crate::room::ReflectionHrtf;
use realfft::RealFftPlanner;
use sotf_host::{Plugin,ProcessContext};
use sotf_host::sofa::SourcePosition;

fn make(rate:u32,sofa:bool,head:f32)->(BinauralDecoderPlugin,Option<crate::head_cue_tests::Fixture>) {
    let file=sofa.then(|| crate::head_cue_tests::sofa(rate,36,0.35));
    let room=RoomModel {dimensions:[6.0,7.0,3.2],listener_position:[2.5,2.7,1.1],absorption:[1.0,1.0,0.0,1.0,1.0,1.0],max_order:1,speed_of_sound:343.0};
    let mut p=BinauralDecoderPlugin::new(1,256,file.as_ref().map(|f|f.path.clone()),1.0,0.0,false,120.0,2.0,0.0,room);
    p.smoothing.head_yaw_deg.reset(head);
    p.initialize(f64::from(rate)).unwrap();
    p.config.crossfade_ms=10.0;
    p.hrtf_update_tx.take();if let Some(worker)=p.hrtf_update_thread.take(){worker.join().unwrap();}
    (p,file)
}

fn expected(p:&BinauralDecoderPlugin,head:f32)->(usize,[f32;2]) {
    let r=p.room.cached_reflections[0].iter().find(|r| r.gain>0.0).unwrap();
    let target=SourcePosition::new(r.azimuth_deg-head,r.elevation_deg,1.0);
    let state=p.state.load_full();
    let ear=if let Some(sofa)=&state._hrtf_data {
        let fft=RealFftPlanner::<f32>::new().plan_fft_forward(256);
        let near=sofa.find_three_nearest(&target);let weights=crate::hrtf::calculate_vbap_gains(&target,&near,sofa);
        let (l,r)=crate::hrtf::interpolate_hrtf_frequency_domain(&near,&weights,sofa,256,p.config.sample_rate,&fft,0.0,target.azimuth,target.elevation);
        let h=ReflectionHrtf::from_freq_domain(l,r);[h.left_gain_broadband,h.right_gain_broadband]
    }else{
        let y=f64::from(target.azimuth).to_radians().sin();
        [((1.0+y)*0.5).sqrt() as f32,((1.0-y)*0.5).sqrt() as f32]
    };
    (r.delay_samples,[r.gain*ear[0],r.gain*ear[1]])
}

fn pulse(p:&mut BinauralDecoderPlugin,rate:u32,warm:usize)->Vec<f32> {
    let mut result=vec![0.0;warm*2];
    if warm>0 {p.process(&vec![0.0;warm],&mut result,&ProcessContext::new(rate,warm)).unwrap();}
    let mut first=[0.0;2];p.process(&[0.25],&mut first,&ProcessContext::new(rate,1)).unwrap();result.extend(first);
    loop {let mut out=[0.0;14];let drain=p.drain(&mut out,&ProcessContext::new(rate,7)).unwrap();result.extend_from_slice(&out[..drain.frames*2]);if drain.complete{break;}}
    result
}

#[test]
fn held_head_pose_rotates_native_and_fallback_reflection_audio() {
    for rate in [44100,48000,96000] {for sofa in [false,true] {for head in [-90.0,0.0,90.0] {
        let (mut p,_file)=make(rate,sofa,head);let (delay,gain)=expected(&p,head);
        let audio=pulse(&mut p,rate,0);let index=(p.latency_samples()+delay)*2;
        let error=(audio[index]-0.25*gain[0]).abs().max((audio[index+1]-0.25*gain[1]).abs());
        println!("REFLECTION_HELD rate={rate} sofa={sofa} head={head} max_error={error}");
        assert!(error<2.0e-5,"held reflection head pose {rate}/{sofa}/{head}: {error}");
    }}}
}

#[test]
fn worker_prepared_pose_updates_reflection_audio_with_direct_filters() {
    for rate in [44100,48000,96000] {for head in [-90.0,90.0] {
        let (mut p,_file)=make(rate,true,0.0);let (delay,gain)=expected(&p,head);
        let base=p.state.load_full();let sofa=base._hrtf_data.as_ref().unwrap();
        let fft=RealFftPlanner::<f32>::new().plan_fft_forward(256);
        let prepared=crate::hrtf::prepare_hrtf_spectra(sofa,256,f64::from(rate),&fft);
        let state=BinauralDecoderPlugin::compute_head_rotated_hrtf_state(&base,&p.config,&prepared,&p.fft,&[],(head,0.0,0.0)).unwrap();
        p.state.store(state);
        let warm=(rate as usize/50+1024).div_ceil(p.config.hop_size)*p.config.hop_size;
        let audio=pulse(&mut p,rate,warm);let index=(warm+p.latency_samples()+delay)*2;
        let error=(audio[index]-0.25*gain[0]).abs().max((audio[index+1]-0.25*gain[1]).abs());
        println!("REFLECTION_WORKER rate={rate} head={head} max_error={error}");
        assert!(error<2.0e-5,"worker reflection pose {rate}/{head}: {error}");
    }}
}
